content:
:root {
  --bg-primary: #08090f;
  --bg-glass: rgba(18, 22, 34, 0.72);
  --bg-glass-active: rgba(36, 44, 68, 0.85);
  --border-glass: rgba(255, 255, 255, 0.12);
  --border-focus: rgba(99, 179, 237, 0.6);
  --text-main: #f0f4f8;
  --text-muted: #94a3b8;
  --accent-cyan: #38bdf8;
  --accent-purple: #c084fc;
  --accent-pink: #f472b6;
  --accent-burst: #fbbf24;
  --shadow-panel: 0 16px 40px -8px rgba(0, 0, 0, 0.6), 0 0 1px 1px rgba(255, 255, 255, 0.08);
  --shadow-glow: 0 0 20px rgba(56, 189, 248, 0.35);
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  --transition-fast: 0.18s ease;
  --transition-smooth: 0.28s cubic-bezier(0.16, 1, 0.3, 1);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  user-select: none;
  -webkit-user-select: none;
}

html, body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background-color: var(--bg-primary);
  font-family: var(--font-sans);
  color: var(--text-main);
  touch-action: none;
}

#root {
  width: 100%;
  height: 100%;
}

/* アプリ全体コンテナ */
.app-container {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: radial-gradient(circle at 50% 50%, #111827 0%, #030712 100%);
}

/* キャンバス描画領域 */
.canvas-container {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 1;
  cursor: crosshair;
}

.canvas-container canvas {
  display: block;
  width: 100%;
  height: 100%;
}

/* UIレイヤー */
.ui-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 10;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 20px;
}

/* 上部タイトルバッジ */
.header-badge {
  pointer-events: auto;
  align-self: flex-start;
  display: inline-flex;
  align-items: center;
  gap: 10px;
  background: var(--bg-glass);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid var(--border-glass);
  border-radius: 9999px;
  padding: 8px 18px;
  font-size: 0.88rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: #fff;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.4);
  transition: transform var(--transition-smooth), border-color var(--transition-fast), box-shadow var(--transition-fast);
}

.header-badge:hover {
  transform: translateY(-1px);
  border-color: var(--border-focus);
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.4), var(--shadow-glow);
}

/* 下部操作ヒント */
.hint-badge {
  pointer-events: none;
  align-self: center;
  background: rgba(15, 23, 42, 0.75);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 9999px;
  padding: 8px 20px;
  font-size: 0.82rem;
  color: var(--text-muted);
  text-align: center;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.3);
  animation: fadeInHint 0.8s ease-out;
  z-index: 15;
}

@keyframes fadeInHint {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* パフォーマンス/情報オーバーレイ */
.stats-overlay {
  pointer-events: none;
  position: absolute;
  top: 20px;
  right: 20px;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 4px;
  font-family: monospace;
  font-size: 0.78rem;
  color: rgba(255, 255, 255, 0.7);
  background: rgba(10, 15, 28, 0.5);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  padding: 6px 12px;
  border-radius: 8px;
  border: 1px solid rgba(255, 255, 255, 0.06);
}

/* コントロールパネル */
.controls-panel {
  pointer-events: auto;
  position: absolute;
  top: 76px;
  right: 20px;
  width: 320px;
  max-width: calc(100vw - 40px);
  max-height: calc(100vh - 100px);
  background: var(--bg-glass);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid var(--border-glass);
  border-radius: 16px;
  box-shadow: var(--shadow-panel);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  transition: all var(--transition-smooth);
  z-index: 20;
}

.controls-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 18px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  font-size: 0.92rem;
  font-weight: 600;
  color: #fff;
}

.controls-toggle-btn {
  background: transparent;
  border: none;
  color: var(--text-muted);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 4px;
  border-radius: 6px;
  transition: color var(--transition-fast), background var(--transition-fast);
}

.controls-toggle-btn:hover {
  color: #fff;
  background: rgba(255, 255, 255, 0.08);
}

.controls-toggle-btn:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 1px;
}

.controls-body {
  padding: 16px 18px 24px;
  overflow-y: auto;
  overscroll-behavior: contain;
  display: flex;
  flex-direction: column;
  gap: 16px;
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, 0.25) transparent;
}

.controls-body::-webkit-scrollbar {
  width: 6px;
}

.controls-body::-webkit-scrollbar-track {
  background: transparent;
}

.controls-body::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.22);
  border-radius: 6px;
}

.controls-body::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 255, 255, 0.35);
}

/* 設定グループ */
.control-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.control-label {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.8rem;
  font-weight: 500;
  color: var(--text-muted);
}

.control-value {
  color: var(--accent-cyan);
  font-family: monospace;
  font-weight: 600;
  font-size: 0.78rem;
}

/* スライダー */
.control-slider {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 6px;
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.12);
  outline: none;
  cursor: pointer;
  transition: background var(--transition-fast);
}

.control-slider:hover {
  background: rgba(255, 255, 255, 0.18);
}

.control-slider:focus-visible {
  box-shadow: 0 0 0 2px var(--border-focus);
}

.control-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: #fff;
  box-shadow: var(--shadow-glow);
  border: 2px solid var(--accent-cyan);
  cursor: pointer;
  transition: transform var(--transition-fast), box-shadow var(--transition-fast);
}

.control-slider::-webkit-slider-thumb:hover {
  transform: scale(1.15);
  box-shadow: 0 0 16px var(--accent-cyan);
}

.control-slider::-moz-range-thumb {
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: #fff;
  box-shadow: var(--shadow-glow);
  border: 2px solid var(--accent-cyan);
  cursor: pointer;
  transition: transform var(--transition-fast), box-shadow var(--transition-fast);
}

.control-slider::-moz-range-thumb:hover {
  transform: scale(1.15);
  box-shadow: 0 0 16px var(--accent-cyan);
}

/* テーマグリッド */
.theme-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.theme-btn {
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid var(--border-glass);
  border-radius: 8px;
  color: var(--text-muted);
  font-size: 0.75rem;
  padding: 8px 4px;
  cursor: pointer;
  text-align: center;
  transition: all var(--transition-fast);
  white-space: nowrap;
}

.theme-btn:hover {
  background: rgba(255, 255, 255, 0.1);
  color: #fff;
  border-color: rgba(255, 255, 255, 0.25);
}

.theme-btn:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 1px;
}

.theme-btn-active {
  background: rgba(56, 189, 248, 0.15);
  border-color: var(--accent-cyan);
  color: #fff;
  font-weight: 600;
  box-shadow: var(--shadow-glow);
}

/* モード切り替えボタン群 */
.mode-buttons {
  display: flex;
  background: rgba(0, 0, 0, 0.28);
  padding: 4px;
  border-radius: 10px;
  border: 1px solid rgba(255, 255, 255, 0.06);
  gap: 4px;
}

.mode-btn {
  flex: 1;
  background: transparent;
  border: none;
  border-radius: 6px;
  padding: 7px 4px;
  color: var(--text-muted);
  font-size: 0.78rem;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition-fast);
  text-align: center;
}

.mode-btn:hover {
  color: #fff;
}

.mode-btn:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 1px;
}

.mode-btn-active {
  background: var(--bg-glass-active);
  color: #fff;
  font-weight: 600;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.2);
}

/* アクションボタン群 */
.action-buttons {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin-top: 4px;
}

.action-btn {
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid var(--border-glass);
  border-radius: 8px;
  color: var(--text-main);
  padding: 9px 12px;
  font-size: 0.8rem;
  font-weight: 500;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  transition: all var(--transition-fast);
}

.action-btn:hover {
  background: rgba(255, 255, 255, 0.12);
  border-color: rgba(255, 255, 255, 0.22);
}

.action-btn:active {
  transform: scale(0.97);
}

.action-btn:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 1px;
}

.action-btn-burst {
  background: linear-gradient(135deg, rgba(244, 114, 182, 0.2), rgba(192, 132, 252, 0.2));
  border-color: rgba(192, 132, 252, 0.45);
  color: #fff;
  font-weight: 600;
}

.action-btn-burst:hover {
  background: linear-gradient(135deg, rgba(244, 114, 182, 0.35), rgba(192, 132, 252, 0.35));
  border-color: var(--accent-pink);
  color: var(--accent-burst);
  box-shadow: 0 0 16px rgba(192, 132, 252, 0.4);
}

/* レスポンシブ対応 */
@media (max-width: 640px) {
  .ui-overlay {
    padding: 12px;
    padding-bottom: calc(12px + env(safe-area-inset-bottom, 0px));
  }

  .header-badge {
    padding: 6px 14px;
    font-size: 0.8rem;
  }

  .stats-overlay {
    top: 12px;
    right: 12px;
    font-size: 0.7rem;
    padding: 4px 8px;
  }

  /* モバイル表示時はヒントをヘッダー下の上部へ配置し、下部固定のパネルと重ならないように保護 */
  .hint-badge {
    position: absolute;
    top: 54px;
    left: 50%;
    transform: translateX(-50%);
    width: max-content;
    max-width: calc(100vw - 24px);
    margin: 0;
    font-size: 0.72rem;
    padding: 6px 12px;
    white-space: nowrap;
    text-overflow: ellipsis;
    overflow: hidden;
  }

  .controls-panel {
    top: auto;
    bottom: calc(12px + env(safe-area-inset-bottom, 0px));
    right: 12px;
    left: 12px;
    width: auto;
    max-width: none;
    max-height: 52vh;
    z-index: 20;
  }

  .controls-body {
    padding: 14px 16px calc(20px + env(safe-area-inset-bottom, 0px));
    gap: 14px;
  }
}

/**
 * カラーテーマの識別子
 */
export type ColorTheme = 'neon' | 'sakura' | 'fire' | 'aurora' | 'cyber';

/**
 * マウスやタッチポインタに対するパーティクルの物理挙動モード
 * - attract: ポインタに向かって吸い寄せられる引力
 * - repel: ポインタから逃げるように散る反発力
 * - orbit: ポインタの周囲を公転・周回する衛星挙動
 */
export type InteractionMode = 'attract' | 'repel' | 'orbit';

/**
 * パーティクルアニメーションの全体設定パラメータ
 */
export interface ParticleSettings {
  /**
   * 画面上に同時に存在するパーティクルの最大総数
   * @type {number} 100 〜 1500
   */
  particleCount: number;

  /**
   * 粒子の配色パレットテーマ
   */
  colorTheme: ColorTheme;

  /**
   * キャンバス描画時の残像の長さ（1に近いほど長い軌跡が残り、0に近いほど即座に消去）
   * @type {number} 0.02 〜 0.92
   */
  trailLength: number;

  /**
   * パーティクルの基本半径（px単位）
   * @type {number} 1.0 〜 5.0
   */
  particleSize: number;

  /**
   * ポインタに対する引力・斥力・公転力の強さの係数
   * @type {number} 0.2 〜 2.0
   */
  attractionStrength: number;

  /**
   * ポインタに対するインタラクション物理モード
   */
  interactionMode: InteractionMode;

  /**
   * 描画時に加算合成（'lighter'）と光彩オーラ効果を付与するかどうかのフラグ
   */
  glowEffect: boolean;
}

/**
 * スライダー等の数値設定用の最小値・最大値・ステップ幅の制約定義
 */
export interface SettingLimit {
  min: number;
  max: number;
  step: number;
}

/**
 * 各数値パラメータの設定可能レンジ定義
 */
export const SETTING_LIMITS: {
  particleCount: SettingLimit;
  particleSize: SettingLimit;
  attractionStrength: SettingLimit;
  trailLength: SettingLimit;
} = {
  particleCount: {
    min: 100,
    max: 1500,
    step: 50
  },
  particleSize: {
    min: 1.0,
    max: 5.0,
    step: 0.2
  },
  attractionStrength: {
    min: 0.2,
    max: 2.0,
    step: 0.1
  },
  trailLength: {
    min: 0.02,
    max: 0.92,
    step: 0.02
  }
} as const;

/**
 * ParticleCanvasコンポーネント用Props
 */
export interface ParticleCanvasProps {
  settings: ParticleSettings;
  burstTrigger: number;
}

/**
 * ControlPanelコンポーネント用Props
 */
export interface ControlPanelProps {
  settings: ParticleSettings;
  onUpdateSettings: (newSettings: Partial<ParticleSettings>) => void;
  onTriggerBurst: () => void;
  onReset: () => void;
}

/**
 * テーマごとのカラーパレット設定
 */
export interface ThemeConfig {
  id: ColorTheme;
  label: string;
  colors: string[];
}

/**
 * アプリ内で選択可能なカラーテーマ一覧
 */
export const THEME_CONFIGS: Record<ColorTheme, ThemeConfig> = {
  aurora: {
    id: 'aurora',
    label: 'オーロラ',
    colors: ['#38bdf8', '#34d399', '#a78bfa', '#6ee7b7', '#818cf8']
  },
  neon: {
    id: 'neon',
    label: '星空ネオン',
    colors: ['#00f0ff', '#7000ff', '#ff007b', '#00e1d9', '#ffffff']
  },
  sakura: {
    id: 'sakura',
    label: 'サクラ',
    colors: ['#f472b6', '#fb7185', '#fbcfe8', '#fda4af', '#ffffff']
  },
  fire: {
    id: 'fire',
    label: '紅蓮炎華',
    colors: ['#ef4444', '#f97316', '#fbbf24', '#f59e0b', '#fee2e2']
  },
  cyber: {
    id: 'cyber',
    label: 'サイバー',
    colors: ['#22c55e', '#a3e635', '#06b6d4', '#4ade80', '#e0e7ff']
  }
};

/**
 * アプリ起動時およびリセット時のデフォルト設定値
 */
export const DEFAULT_SETTINGS: ParticleSettings = {
  particleCount: 500,
  colorTheme: 'aurora',
  trailLength: 0.18,
  particleSize: 2.2,
  attractionStrength: 0.8,
  interactionMode: 'attract',
  glowEffect: true
};

import { useEffect, useRef, useCallback } from 'react';
import { ParticleCanvasProps, THEME_CONFIGS, ParticleSettings } from '../types';

interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  baseRadius: number;
  currentRadius: number;
  color: string;
  alpha: number;
  friction: number;
  wanderAngle: number;
  burstLife?: number;
}

const ParticleCanvas = ({ settings, burstTrigger }: ParticleCanvasProps) => {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const particlesRef = useRef<Particle[]>([]);
  const pointerRef = useRef<{ x: number; y: number; active: boolean }>({
    x: 0,
    y: 0,
    active: false
  });
  const settingsRef = useRef<ParticleSettings>(settings);
  const prevBurstTriggerRef = useRef(burstTrigger);
  const sizeRef = useRef<{ width: number; height: number; dpr: number }>({
    width: window.innerWidth,
    height: window.innerHeight,
    dpr: 1
  });

  // settingsRefを常に最新に保つ（アニメーションループを再起動させないため）
  useEffect(() => {
    settingsRef.current = settings;
  }, [settings]);

  // マウス/タッチ座標とクリックによるバースト
  const triggerBurstAt = useCallback((x: number, y: number) => {
    const burstCount = 65;
    const currentSettings = settingsRef.current;
    const theme = THEME_CONFIGS[currentSettings.colorTheme] || THEME_CONFIGS.aurora;
    const newParticles: Particle[] = [];

    for (let i = 0; i < burstCount; i++) {
      const angle = Math.random() * Math.PI * 2;
      const speed = 3 + Math.random() * 8;
      const color = theme.colors[Math.floor(Math.random() * theme.colors.length)];
      newParticles.push({
        x,
        y,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed,
        baseRadius: currentSettings.particleSize * (1.2 + Math.random() * 1.5),
        currentRadius: currentSettings.particleSize * 2,
        color,
        alpha: 1,
        friction: 0.94,
        wanderAngle: Math.random() * Math.PI * 2,
        burstLife: 60 + Math.floor(Math.random() * 30)
      });
    }

    particlesRef.current = [...particlesRef.current, ...newParticles];
  }, []);

  // 外部からのバーストトリガー
  useEffect(() => {
    if (burstTrigger !== prevBurstTriggerRef.current) {
      prevBurstTriggerRef.current = burstTrigger;
      const { width, height } = sizeRef.current;
      const cx = pointerRef.current.active ? pointerRef.current.x : width / 2;
      const cy = pointerRef.current.active ? pointerRef.current.y : height / 2;
      triggerBurstAt(cx, cy);
    }
  }, [burstTrigger, triggerBurstAt]);

  // パーティクル配列の初期化およびカウント同期・テーマ色反映
  useEffect(() => {
    const { width, height } = sizeRef.current;
    const theme = THEME_CONFIGS[settings.colorTheme] || THEME_CONFIGS.aurora;
    const targetCount = settings.particleCount;
    const currentParticles = particlesRef.current.filter((p) => !p.burstLife);

    if (currentParticles.length < targetCount) {
      const diff = targetCount - currentParticles.length;
      for (let i = 0; i < diff; i++) {
        const color = theme.colors[Math.floor(Math.random() * theme.colors.length)];
        currentParticles.push({
          x: Math.random() * width,
          y: Math.random() * height,
          vx: (Math.random() - 0.5) * 1.5,
          vy: (Math.random() - 0.5) * 1.5,
          baseRadius: settings.particleSize * (0.6 + Math.random() * 0.8),
          currentRadius: settings.particleSize,
          color,
          alpha: 0.3 + Math.random() * 0.7,
          friction: 0.96,
          wanderAngle: Math.random() * Math.PI * 2
        });
      }
    } else if (currentParticles.length > targetCount) {
      currentParticles.length = targetCount;
    }

    // テーマ色および基本サイズの更新
    currentParticles.forEach((p) => {
      p.color = theme.colors[Math.floor(Math.random() * theme.colors.length)];
      p.baseRadius = settings.particleSize * (0.6 + Math.random() * 0.8);
    });

    // 既存バースト粒子も含めて保持
    const bursts = particlesRef.current.filter((p) => !!p.burstLife);
    particlesRef.current = [...currentParticles, ...bursts];
  }, [settings.particleCount, settings.colorTheme, settings.particleSize]);

  // アニメーションループ & ResizeObserverによるサイズ管理（初回のみセットアップ）
  useEffect(() => {
    const canvas = canvasRef.current;
    const container = containerRef.current;
    if (!canvas || !container) return;

    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) return;

    let animationFrameId: number;

    const updateCanvasDimensions = (rectWidth: number, rectHeight: number) => {
      const dpr = window.devicePixelRatio || 1;
      const w = Math.max(1, Math.floor(rectWidth));
      const h = Math.max(1, Math.floor(rectHeight));

      canvas.width = Math.floor(w * dpr);
      canvas.height = Math.floor(h * dpr);
      sizeRef.current = { width: w, height: h, dpr };

      // 画面外に出てしまったパーティクルを現在の領域内に安全にクランプ
      particlesRef.current.forEach((p) => {
        if (p.x > w + 20) p.x = Math.random() * w;
        if (p.y > h + 20) p.y = Math.random() * h;
      });
    };

    const initialRect = container.getBoundingClientRect();
    updateCanvasDimensions(initialRect.width, initialRect.height);

    const resizeObserver = new ResizeObserver((entries) => {
      for (const entry of entries) {
        const { width, height } = entry.contentRect;
        if (width > 0 && height > 0) {
          updateCanvasDimensions(width, height);
        }
      }
    });
    resizeObserver.observe(container);

    const render = () => {
      const { width, height, dpr } = sizeRef.current;
      const currentSettings = settingsRef.current;

      ctx.save();
      ctx.scale(dpr, dpr);

      // トレイル（残像）フェード描画
      ctx.globalCompositeOperation = 'source-over';
      const trailAlpha = Math.max(0.04, Math.min(0.6, 1 - currentSettings.trailLength));
      ctx.fillStyle = `rgba(8, 9, 15, ${trailAlpha})`;
      ctx.fillRect(0, 0, width, height);

      // 光彩（発光）ブラー合成モード
      if (currentSettings.glowEffect) {
        ctx.globalCompositeOperation = 'lighter';
      }

      const pX = pointerRef.current.x;
      const pY = pointerRef.current.y;
      const pActive = pointerRef.current.active;
      const strength = currentSettings.attractionStrength * 1.6;

      const survivingParticles: Particle[] = [];

      for (let i = 0; i < particlesRef.current.length; i++) {
        const p = particlesRef.current[i];

        // バースト専用粒子の寿命処理
        if (p.burstLife !== undefined) {
          p.burstLife -= 1;
          p.alpha = Math.max(0, p.burstLife / 70);
          p.vx *= p.friction;
          p.vy *= p.friction;
          p.x += p.vx;
          p.y += p.vy;

          if (p.burstLife > 0) {
            survivingParticles.push(p);
          }
        } else {
          // 通常パーティクルの物理挙動
          p.wanderAngle += (Math.random() - 0.5) * 0.4;
          const wanderForce = 0.12;
          p.vx += Math.cos(p.wanderAngle) * wanderForce;
          p.vy += Math.sin(p.wanderAngle) * wanderForce;

          if (pActive) {
            const dx = pX - p.x;
            const dy = pY - p.y;
            const distSq = dx * dx + dy * dy;
            const dist = Math.sqrt(distSq) || 1;
            const maxDistance = 420;

            if (dist < maxDistance) {
              const force = (1 - dist / maxDistance) * strength;
              const angle = Math.atan2(dy, dx);

              if (currentSettings.interactionMode === 'attract') {
                p.vx += Math.cos(angle) * force * 1.2;
                p.vy += Math.sin(angle) * force * 1.2;
              } else if (currentSettings.interactionMode === 'repel') {
                p.vx -= Math.cos(angle) * force * 2.2;
                p.vy -= Math.sin(angle) * force * 2.2;
              } else if (currentSettings.interactionMode === 'orbit') {
                const perpAngle = angle + Math.PI / 2;
                const orbitSpeed = force * 2.0;
                p.vx += Math.cos(perpAngle) * orbitSpeed + Math.cos(angle) * force * 0.4;
                p.vy += Math.sin(perpAngle) * orbitSpeed + Math.sin(angle) * force * 0.4;
              }
            }
          }

          p.vx *= p.friction;
          p.vy *= p.friction;
          p.x += p.vx;
          p.y += p.vy;

          // 画面端の折り返し
          if (p.x < -20) p.x = width + 20;
          if (p.x > width + 20) p.x = -20;
          if (p.y < -20) p.y = height + 20;
          if (p.y > height + 20) p.y = -20;

          survivingParticles.push(p);
        }

        // パーティクル描画
        const radius = Math.max(0.8, p.baseRadius);
        ctx.beginPath();
        ctx.arc(p.x, p.y, radius, 0, Math.PI * 2);
        ctx.fillStyle = p.color;
        ctx.globalAlpha = p.alpha;
        ctx.fill();

        // 発光オーラ
        if (currentSettings.glowEffect && radius > 1.8) {
          ctx.beginPath();
          ctx.arc(p.x, p.y, radius * 2.5, 0, Math.PI * 2);
          ctx.fillStyle = p.color;
          ctx.globalAlpha = p.alpha * 0.22;
          ctx.fill();
        }
      }

      ctx.restore();
      particlesRef.current = survivingParticles;
      animationFrameId = requestAnimationFrame(render);
    };

    animationFrameId = requestAnimationFrame(render);

    return () => {
      resizeObserver.disconnect();
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  const handlePointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    const rect = e.currentTarget.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    pointerRef.current = { x, y, active: true };
    triggerBurstAt(x, y);
  };

  const handlePointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    const rect = e.currentTarget.getBoundingClientRect();
    pointerRef.current = {
      x: e.clientX - rect.left,
      y: e.clientY - rect.top,
      active: true
    };
  };

  const handlePointerUp = () => {
    pointerRef.current.active = false;
  };

  const handlePointerLeave = () => {
    pointerRef.current.active = false;
  };

  return (
    <div
      ref={containerRef}
      className="canvas-container"
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerUp}
      onPointerLeave={handlePointerLeave}
    >
      <canvas ref={canvasRef} />
    </div>
  );
};

export default ParticleCanvas;

import { useState, useEffect, useRef, useCallback } from 'react';
import { ChevronDown, ChevronUp, Sparkles, RotateCcw } from 'lucide-react';
import {
  ControlPanelProps,
  ColorTheme,
  InteractionMode,
  THEME_CONFIGS,
  SETTING_LIMITS,
  ParticleSettings
} from '../types';

interface SliderValues {
  particleCount: number;
  particleSize: number;
  attractionStrength: number;
  trailLength: number;
}

const ControlPanel = ({
  settings,
  onUpdateSettings,
  onTriggerBurst,
  onReset
}: ControlPanelProps) => {
  const [isOpen, setIsOpen] = useState(true);

  // スライダーの滑らかな操作性と親の不要な高頻度再レンダリング防止のためのローカルステート
  const [localValues, setLocalValues] = useState<SliderValues>({
    particleCount: settings.particleCount,
    particleSize: settings.particleSize,
    attractionStrength: settings.attractionStrength,
    trailLength: settings.trailLength
  });

  const pendingUpdatesRef = useRef<Partial<ParticleSettings>>({});
  const throttleTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // 親の settings がリセット等で外部から更新された場合にローカルステートを同期
  useEffect(() => {
    setLocalValues({
      particleCount: settings.particleCount,
      particleSize: settings.particleSize,
      attractionStrength: settings.attractionStrength,
      trailLength: settings.trailLength
    });
  }, [
    settings.particleCount,
    settings.particleSize,
    settings.attractionStrength,
    settings.trailLength
  ]);

  // 保留中の設定更新を親へ反映
  const flushUpdates = useCallback(() => {
    if (throttleTimeoutRef.current) {
      clearTimeout(throttleTimeoutRef.current);
      throttleTimeoutRef.current = null;
    }
    if (Object.keys(pendingUpdatesRef.current).length > 0) {
      onUpdateSettings(pendingUpdatesRef.current);
      pendingUpdatesRef.current = {};
    }
  }, [onUpdateSettings]);

  // アンマウント時に未送信の変更をフラッシュ＆タイマークリア
  useEffect(() => {
    return () => {
      if (throttleTimeoutRef.current) {
        clearTimeout(throttleTimeoutRef.current);
      }
      if (Object.keys(pendingUpdatesRef.current).length > 0) {
        onUpdateSettings(pendingUpdatesRef.current);
      }
    };
  }, [onUpdateSettings]);

  // スライダードラッグ時のスロットリング更新処理
  const handleSliderChange = (key: keyof SliderValues, val: number) => {
    setLocalValues((prev) => ({ ...prev, [key]: val }));
    pendingUpdatesRef.current = { ...pendingUpdatesRef.current, [key]: val };

    if (!throttleTimeoutRef.current) {
      throttleTimeoutRef.current = setTimeout(() => {
        throttleTimeoutRef.current = null;
        if (Object.keys(pendingUpdatesRef.current).length > 0) {
          onUpdateSettings(pendingUpdatesRef.current);
          pendingUpdatesRef.current = {};
        }
      }, 50);
    }
  };

  const themeList = Object.values(THEME_CONFIGS);

  const modeOptions: { id: InteractionMode; label: string }[] = [
    { id: 'attract', label: '引力追従' },
    { id: 'repel', label: '反発拡散' },
    { id: 'orbit', label: '惑星公転' }
  ];

  const currentThemeLabel = THEME_CONFIGS[settings.colorTheme]?.label || 'オーロラ';
  const currentModeLabel = modeOptions.find((m) => m.id === settings.interactionMode)?.label || '引力追従';

  return (
    <div className="controls-panel">
      <div className="controls-header">
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
          <span>設定コントロール</span>
          {!isOpen && (
            <span
              style={{
                fontSize: '0.72rem',
                color: 'var(--accent-cyan)',
                background: 'rgba(56, 189, 248, 0.12)',
                padding: '2px 8px',
                borderRadius: '9999px',
                fontWeight: 500
              }}
            >
              {currentThemeLabel} · {currentModeLabel} · {localValues.particleCount}
            </span>
          )}
        </div>
        <button
          type="button"
          className="controls-toggle-btn"
          onClick={() => setIsOpen(!isOpen)}
          aria-label={isOpen ? 'パネルを閉じる' : 'パネルを開く'}
        >
          {isOpen ? <ChevronUp size={18} /> : <ChevronDown size={18} />}
        </button>
      </div>

      {isOpen && (
        <div className="controls-body">
          {/* カラーテーマ選択 */}
          <div className="control-group">
            <div className="control-label">
              <span>カラーテーマ</span>
              <span className="control-value">{currentThemeLabel}</span>
            </div>
            <div className="theme-grid">
              {themeList.map((th) => {
                const isActive = settings.colorTheme === th.id;
                return (
                  <button
                    key={th.id}
                    type="button"
                    className={`theme-btn ${isActive ? 'theme-btn-active' : ''}`}
                    onClick={() => onUpdateSettings({ colorTheme: th.id as ColorTheme })}
                  >
                    {th.label}
                  </button>
                );
              })}
            </div>
          </div>

          {/* インタラクションモード切替 */}
          <div className="control-group">
            <div className="control-label">
              <span>挙動モード</span>
            </div>
            <div className="mode-buttons">
              {modeOptions.map((mode) => {
                const isActive = settings.interactionMode === mode.id;
                return (
                  <button
                    key={mode.id}
                    type="button"
                    className={`mode-btn ${isActive ? 'mode-btn-active' : ''}`}
                    onClick={() => onUpdateSettings({ interactionMode: mode.id })}
                  >
                    {mode.label}
                  </button>
                );
              })}
            </div>
          </div>

          {/* 発光（Glow）エフェクトトグル */}
          <div className="control-group">
            <div className="control-label">
              <span>発光エフェクト (Glow)</span>
              <span className="control-value">{settings.glowEffect ? 'ON' : 'OFF'}</span>
            </div>
            <div className="mode-buttons">
              <button
                type="button"
                className={`mode-btn ${settings.glowEffect ? 'mode-btn-active' : ''}`}
                onClick={() => onUpdateSettings({ glowEffect: true })}
                aria-pressed={settings.glowEffect}
              >
                発光 ON
              </button>
              <button
                type="button"
                className={`mode-btn ${!settings.glowEffect ? 'mode-btn-active' : ''}`}
                onClick={() => onUpdateSettings({ glowEffect: false })}
                aria-pressed={!settings.glowEffect}
              >
                発光 OFF
              </button>
            </div>
          </div>

          {/* 粒子数スライダー */}
          <div className="control-group">
            <label htmlFor="particle-count-slider" className="control-label">
              <span>粒子数</span>
              <span className="control-value">{localValues.particleCount}</span>
            </label>
            <input
              id="particle-count-slider"
              type="range"
              className="control-slider"
              min={SETTING_LIMITS.particleCount.min}
              max={SETTING_LIMITS.particleCount.max}
              step={SETTING_LIMITS.particleCount.step}
              value={localValues.particleCount}
              aria-label="粒子数"
              aria-valuemin={SETTING_LIMITS.particleCount.min}
              aria-valuemax={SETTING_LIMITS.particleCount.max}
              aria-valuenow={localValues.particleCount}
              onChange={(e) => handleSliderChange('particleCount', Number(e.target.value))}
              onPointerUp={flushUpdates}
              onKeyUp={flushUpdates}
            />
          </div>

          {/* 粒子サイズスライダー */}
          <div className="control-group">
            <label htmlFor="particle-size-slider" className="control-label">
              <span>粒子サイズ</span>
              <span className="control-value">{localValues.particleSize.toFixed(1)}px</span>
            </label>
            <input
              id="particle-size-slider"
              type="range"
              className="control-slider"
              min={SETTING_LIMITS.particleSize.min}
              max={SETTING_LIMITS.particleSize.max}
              step={SETTING_LIMITS.particleSize.step}
              value={localValues.particleSize}
              aria-label="粒子サイズ"
              aria-valuemin={SETTING_LIMITS.particleSize.min}
              aria-valuemax={SETTING_LIMITS.particleSize.max}
              aria-valuenow={localValues.particleSize}
              onChange={(e) => handleSliderChange('particleSize', Number(e.target.value))}
              onPointerUp={flushUpdates}
              onKeyUp={flushUpdates}
            />
          </div>

          {/* 追従強度スライダー */}
          <div className="control-group">
            <label htmlFor="attraction-strength-slider" className="control-label">
              <span>作用の強さ</span>
              <span className="control-value">{localValues.attractionStrength.toFixed(1)}</span>
            </label>
            <input
              id="attraction-strength-slider"
              type="range"
              className="control-slider"
              min={SETTING_LIMITS.attractionStrength.min}
              max={SETTING_LIMITS.attractionStrength.max}
              step={SETTING_LIMITS.attractionStrength.step}
              value={localValues.attractionStrength}
              aria-label="作用の強さ"
              aria-valuemin={SETTING_LIMITS.attractionStrength.min}
              aria-valuemax={SETTING_LIMITS.attractionStrength.max}
              aria-valuenow={localValues.attractionStrength}
              onChange={(e) => handleSliderChange('attractionStrength', Number(e.target.value))}
              onPointerUp={flushUpdates}
              onKeyUp={flushUpdates}
            />
          </div>

          {/* 残像・軌跡の長さスライダー */}
          <div className="control-group">
            <label htmlFor="trail-length-slider" className="control-label">
              <span>軌跡の残像度</span>
              <span className="control-value">{Math.round(localValues.trailLength * 100)}%</span>
            </label>
            <input
              id="trail-length-slider"
              type="range"
              className="control-slider"
              min={SETTING_LIMITS.trailLength.min}
              max={SETTING_LIMITS.trailLength.max}
              step={SETTING_LIMITS.trailLength.step}
              value={localValues.trailLength}
              aria-label="軌跡の残像度"
              aria-valuemin={SETTING_LIMITS.trailLength.min}
              aria-valuemax={SETTING_LIMITS.trailLength.max}
              aria-valuenow={localValues.trailLength}
              onChange={(e) => handleSliderChange('trailLength', Number(e.target.value))}
              onPointerUp={flushUpdates}
              onKeyUp={flushUpdates}
            />
          </div>

          {/* アクションボタン */}
          <div className="action-buttons">
            <button
              type="button"
              className="action-btn action-btn-burst"
              onClick={onTriggerBurst}
            >
              <Sparkles size={16} />
              <span>バースト発動</span>
            </button>
            <button
              type="button"
              className="action-btn"
              onClick={onReset}
            >
              <RotateCcw size={16} />
              <span>リセット</span>
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default ControlPanel;

import { useState, useEffect, useRef, useCallback } from 'react';
import { Sparkles } from 'lucide-react';
import { ParticleSettings, DEFAULT_SETTINGS } from './types';
import ParticleCanvas from './components/ParticleCanvas';
import ControlPanel from './components/ControlPanel';

interface StatsOverlayProps {
  particleCount: number;
}

const StatsOverlay = ({ particleCount }: StatsOverlayProps) => {
  const [fps, setFps] = useState(60);
  const frameCountRef = useRef(0);
  const lastTimeRef = useRef(performance.now());

  useEffect(() => {
    let animId: number;

    const calculateFps = (now: number) => {
      frameCountRef.current++;
      const elapsed = now - lastTimeRef.current;

      if (elapsed >= 500) {
        setFps(Math.round((frameCountRef.current * 1000) / elapsed));
        frameCountRef.current = 0;
        lastTimeRef.current = now;
      }

      animId = requestAnimationFrame(calculateFps);
    };

    animId = requestAnimationFrame(calculateFps);
    return () => cancelAnimationFrame(animId);
  }, []);

  return (
    <div className="stats-overlay">
      <div>FPS: {fps}</div>
      <div>粒子数: {particleCount}</div>
    </div>
  );
};

const App = () => {
  const [settings, setSettings] = useState<ParticleSettings>(DEFAULT_SETTINGS);
  const [burstTrigger, setBurstTrigger] = useState(0);

  const handleUpdateSettings = useCallback((newSettings: Partial<ParticleSettings>) => {
    setSettings((prev) => ({ ...prev, ...newSettings }));
  }, []);

  const handleTriggerBurst = useCallback(() => {
    setBurstTrigger((prev) => prev + 1);
  }, []);

  const handleReset = useCallback(() => {
    setSettings(DEFAULT_SETTINGS);
  }, []);

  return (
    <div className="app-container">
      {/* 高精細Canvasパーティクル描画 */}
      <ParticleCanvas settings={settings} burstTrigger={burstTrigger} />

      {/* 画面オーバーレイUI */}
      <div className="ui-overlay">
        {/* 左上ヘッダーバッジ */}
        <div className="header-badge">
          <Sparkles size={16} color="#38bdf8" />
          <span>オーロラ・パーティクル</span>
        </div>

        {/* 右上パフォーマンスインジケーター（独立レンダリング） */}
        <StatsOverlay particleCount={settings.particleCount} />

        {/* コントロールパネル */}
        <ControlPanel
          settings={settings}
          onUpdateSettings={handleUpdateSettings}
          onTriggerBurst={handleTriggerBurst}
          onReset={handleReset}
        />

        {/* 下部操作ガイド */}
        <div className="hint-badge">
          ポインタ移動 / 指で追従 ・ タップで花火バースト拡散
        </div>
      </div>
    </div>
  );
};

export default App;
